package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class SaveSetting {
    public void save(@PathVariable("sheetId") String sheetId, @Val ValidSetting setting, @Val RollupFigures before,
            Settings settings, Sheets sheets, Rollup rollup, Audit audit, ObjectResponse<SettingsResponse> response) {
        if (setting.roles() != null) {
            settings.setPermission(sheetId, setting.key().substring(ValidateSetting.PERM.length()), setting.roles());
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + setting.roles());
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        if (ValidateSetting.POLICY_DATE.equals(setting.key())
                || ValidateSetting.PERIOD_NUMBERING_FROM.equals(setting.key())) {
            if (setting.roles() != null) {
            settings.setPermission(sheetId, setting.key().substring(ValidateSetting.PERM.length()), setting.roles());
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + setting.roles());
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        if (ValidateSetting.POLICY_DATE.equals(setting.key())) {
                settings.setPolicyDate(sheetId, setting.date());
            } else {
                settings.setPeriodNumberingFrom(sheetId, setting.date());
            }
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + (setting.date() == null ? "" : setting.date().toString()));
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        if (ValidateSetting.ENTRY_DATE.equals(setting.key())) {
            settings.setEntryDate(sheetId, setting.date());
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + (setting.date() == null ? "" : setting.date().toString()));
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        if (ValidateSetting.ESCALATE_AFTER.equals(setting.key())) {
            settings.setEscalateAfter(sheetId, setting.value() == null ? null : setting.value().intValue());
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + (setting.value() == null ? "" : setting.value().toPlainString()));
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        if (ValidateSetting.REVIEW_SLA.equals(setting.key())) {
            settings.setReviewSla(sheetId, setting.value() == null ? null : setting.value().intValue());
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + (setting.value() == null ? "" : setting.value().toPlainString()));
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        if (ValidateSetting.SCORE_MID.equals(setting.key()) || ValidateSetting.SCORE_HIGH.equals(setting.key())) {
            settings.setScoreThreshold(sheetId, setting.key(), setting.value() == null ? null : setting.value().intValue());
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + (setting.value() == null ? "" : setting.value().toPlainString()));
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        if (ValidateSetting.GRACE_DAYS.equals(setting.key())) {
            settings.setGraceDays(sheetId, setting.value() == null ? null : setting.value().intValue());
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + (setting.value() == null ? "" : setting.value().toPlainString()));
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        if (ValidateSetting.FISCAL_START_MONTH.equals(setting.key())) {
            settings.setFiscalStartMonth(sheetId, setting.value().intValue());
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + setting.value().intValue());
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        if (ValidateSetting.PROOF_KINDS.equals(setting.key())) {
            settings.setProofKinds(sheetId, setting.text());
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + setting.text());
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        if (ValidateSetting.DEFAULT_GRADE.equals(setting.key())) {
            settings.setDefaultGrade(sheetId, setting.text());
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + setting.text());
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        if (ValidateSetting.PARENT.equals(setting.key())) {
            settings.setParent(sheetId, setting.text());
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + (setting.text() == null ? "" : setting.text()));
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        if (ValidateSetting.ALERT_THRESHOLD.equals(setting.key())) {
            settings.setAlertThreshold(sheetId, setting.value());
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + (setting.value() == null ? "" : setting.value().toPlainString()));
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        if (ValidateSetting.POT.equals(setting.key())) {
            settings.setPot(sheetId, setting.value());
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + (setting.value() == null ? "" : setting.value().toPlainString()));
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        // Recorded from its from-date (the sheet's today when none was given), keeping the values recorded from other dates.
        settings.setFrom(sheetId, setting.key(), setting.from() != null ? setting.from() : sheets.today(sheetId), setting.value());
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                + " key=" + setting.key() + " value=" + (setting.text() != null ? setting.text() : setting.value() == null ? "" : setting.value().toPlainString())
                + (setting.from() == null ? "" : " from=" + setting.from()));
        rollup.recordChanges(sheetId, setting.user(), before);
        response.send(settings.load(sheetId));
    }
}

    public void setReviewSla(String sheetId, Integer days) {
        sheets.today(sheetId);
        jdbc.update("UPDATE sheet SET review_sla = ? WHERE id = ?", days, sheetId);
        plainHistory(sheetId, REVIEW_SLA, days == null ? "" : String.valueOf(days));
    }

    /** The sheet's score threshold (score-mid or score-high); null when blank. */
    public Integer scoreThreshold(String sheetId, String key) {
        sheets.today(sheetId); // the sheet's row holds the score thresholds
        return jdbc.queryForObject("SELECT " + scoreColumn(key) + " FROM sheet WHERE id = ?", Integer.class, sheetId);
    }

    public void setScoreThreshold(String sheetId, String key, Integer value) {
        sheets.today(sheetId);
        jdbc.update("UPDATE sheet SET " + scoreColumn(key) + " = ? WHERE id = ?", value, sheetId);
        plainHistory(sheetId, key, value == null ? "" : String.valueOf(value));
    }

    private static String scoreColumn(String key) {
        return ValidateSetting.SCORE_HIGH.equals(key) ? "score_high" : "score_mid";
    }

    /** The sheet's proof kinds, in the order set; empty when none. */
    public List<String> proofKinds(String sheetId) {
        sheets.today(sheetId); // the sheet's row holds the proof kinds
        BigDecimal limit = clerkLimit(sheetId);
        BigDecimal cap = cap(sheetId);
        BigDecimal threshold = proofThreshold(sheetId, today);
        BigDecimal noteThreshold = noteThreshold(sheetId, today);
        BigDecimal reviewThreshold = reviewThreshold(sheetId, today);
        InForce rounding = on(sheetId, ValidateSetting.ROUNDING, today);
        LocalDate policy = policyDateSet(sheetId);
        LocalDate numbering = periodNumberingFrom(sheetId);
        Integer grace = graceDays(sheetId);
        Integer escalate = escalateAfter(sheetId);
        Integer reviewSla = reviewSla(sheetId);
        Integer scoreMid = scoreThreshold(sheetId, ValidateSetting.SCORE_MID);
        Integer scoreHigh = scoreThreshold(sheetId, ValidateSetting.SCORE_HIGH);
        LocalDate entry = entryDate(sheetId);
        BigDecimal pot = pot(sheetId);
        BigDecimal alert = alertThreshold(sheetId);
        String parent = parent(sheetId);
        List<RoleResponse> roles = jdbc.query(
                "SELECT user_name, role FROM sheet_role WHERE sheet_id = ? ORDER BY user_name",
                (rs, i) -> new RoleResponse(rs.getString(1), rs.getString(2)), sheetId);
        java.util.Map<String, String> gradeTerms = new java.util.TreeMap<>();
        for (String grade : ValidateSetting.GRADES) {
            Integer own = gradeTerms(sheetId, grade, today);
            if (own != null) {
                gradeTerms.put(grade, String.valueOf(own));
            }
        }
        java.util.Map<String, String> perms = new java.util.LinkedHashMap<>();
        for (String action : ValidateSetting.ACTIONS) {
            perms.put(action, permission(sheetId, action));
        }
        return new SettingsResponse(limit == null ? "" : limit.setScale(2).toPlainString(),
                floor(sheetId, today).setScale(2).toPlainString(), String.valueOf(terms(sheetId, today)),
                latePct(sheetId, today).setScale(2).toPlainString(), policy == null ? "" : policy.toString(),
                numbering == null ? "" : numbering.toString(), roles, gradeTerms,
                cap == null ? "" : cap.setScale(2).toPlainString(), dated(sheetId),
                threshold == null ? "" : threshold.setScale(2).toPlainString(), perms,
                grace == null ? "" : String.valueOf(grace), jdbc.query(
                        "SELECT user_name, from_date, to_date, delegated_by FROM sheet_delegation WHERE sheet_id = ? ORDER BY seq",
                        (rs, i) -> new DelegationResponse(rs.getString(1), rs.getDate(2).toLocalDate().toString(),
                                rs.getDate(3).toLocalDate().toString(), rs.getString(4)), sheetId),
                noteThreshold == null ? "" : noteThreshold.setScale(2).toPlainString(), entry == null ? "" : entry.toString(), pot == null ? "" : pot.toPlainString(),
                parent == null ? "" : parent, String.valueOf(fiscalStartMonth(sheetId)),
                alert == null ? "" : alert.toPlainString(), rounding == null ? "" : net.officefloor.hq.app.claim.Rounding.name(rounding.value()),
                reviewThreshold == null ? "" : reviewThreshold.setScale(2).toPlainString(),
                escalate == null ? "" : String.valueOf(escalate), reviewSla == null ? "" : String.valueOf(reviewSla),
                String.join(",", proofKinds(sheetId)), Objects.toString(defaultGradeSet(sheetId), ""),
                scoreMid == null ? "" : String.valueOf(scoreMid), scoreHigh == null ? "" : String.valueOf(scoreHigh));
    }
}
        dated.forEach((key, byFrom) -> byFrom.forEach((from, value) -> datedShown.computeIfAbsent(key, k -> new ArrayList<>())
                .add(new DatedValue(from.toString(), value[0] == null ? "" : ValidateSetting.ROUNDING.equals(key)
                        ? net.officefloor.hq.app.claim.Rounding.name(value[0]) : key.startsWith("terms")
                        ? String.valueOf(value[0].intValue()) : value[0].setScale(2).toPlainString()))));
        BigDecimal limit = on.apply(ValidateSetting.CLERK_LIMIT);
        BigDecimal cap = on.apply(ValidateSetting.CAP);
        BigDecimal threshold = on.apply(ValidateSetting.PROOF_THRESHOLD);
        BigDecimal noteThreshold = on.apply(ValidateSetting.NOTE_THRESHOLD);
        BigDecimal reviewThreshold = on.apply(ValidateSetting.REVIEW_THRESHOLD);
        BigDecimal floor = on.apply(ValidateSetting.FLOOR);
        BigDecimal terms = on.apply(ValidateSetting.TERMS);
        BigDecimal latePct = on.apply(ValidateSetting.LATE_PCT);
        Map<String, String> gradeTerms = new TreeMap<>();
        for (String grade : List.of("A", "B", "C")) {
            BigDecimal own = on.apply(ValidateSetting.GRADE_TERMS + grade);
            if (own != null) gradeTerms.put(grade, String.valueOf(own.intValue()));
        }
        // The policy date: the latest set (null: blank).
        List<LocalDate> policies = new ArrayList<>();
        jdbc.query("SELECT policy_date FROM policy_history WHERE sheet_id = ?" + UP_TO + " ORDER BY seq",
                (RowCallbackHandler) rs -> policies.add(local(rs.getDate(1))), sheetId, end);
        LocalDate policy = policies.isEmpty() ? null : policies.get(policies.size() - 1);
        // The undated settings: the latest set for each key.
        Map<String, String> plain = new HashMap<>();
        jdbc.query("SELECT setting_key, setting_value FROM plain_setting_history WHERE sheet_id = ?" + UP_TO + " ORDER BY seq",
                (RowCallbackHandler) rs -> plain.put(rs.getString(1), rs.getString(2)), sheetId, end);
        List<RoleResponse> roles = new ArrayList<>();
        new TreeMap<>(plain).forEach((key, value) -> {
            if (key.startsWith(Settings.ROLE)) roles.add(new RoleResponse(key.substring(Settings.ROLE.length()), value));
        });
        Map<String, String> perms = new LinkedHashMap<>();
        for (String action : ValidateSetting.ACTIONS) {
            perms.put(action, plain.getOrDefault(Settings.PERM + action, ""));
        }
        List<DelegationResponse> delegations = jdbc.query("SELECT user_name, from_date, to_date, delegated_by FROM sheet_delegation"
                + " WHERE sheet_id = ?" + UP_TO + " ORDER BY seq", (rs, i) -> new DelegationResponse(rs.getString(1),
                        rs.getDate(2).toLocalDate().toString(), rs.getDate(3).toLocalDate().toString(), rs.getString(4)),
                sheetId, end);
        return new SettingsResponse(limit == null ? "" : limit.setScale(2).toPlainString(),
                (floor == null ? Settings.START_FLOOR : floor).setScale(2).toPlainString(),
                String.valueOf(terms == null ? Settings.START_TERMS : terms.intValue()),
                (latePct == null ? Settings.START_LATE_PCT : latePct).setScale(2).toPlainString(),
                policy == null ? "" : policy.toString(), plain.getOrDefault(Settings.NUMBERING, ""), roles, gradeTerms,
                cap == null ? "" : cap.setScale(2).toPlainString(), datedShown,
                threshold == null ? "" : threshold.setScale(2).toPlainString(), perms, plain.getOrDefault(Settings.GRACE, ""),
                delegations, noteThreshold == null ? "" : noteThreshold.setScale(2).toPlainString(),
                plain.getOrDefault(Settings.ENTRY, ""), plain.getOrDefault(Settings.POT, ""),
                Objects.toString(sheets.parent(sheetId), ""), // the parent is not dated: as it is now
                plain.getOrDefault(Settings.FISCAL, "1"), plain.getOrDefault(Settings.ALERT, ""),
                net.officefloor.hq.app.claim.Rounding.name(on.apply(ValidateSetting.ROUNDING)),
                reviewThreshold == null ? "" : reviewThreshold.setScale(2).toPlainString(),
                plain.getOrDefault(Settings.ESCALATE, ""), plain.getOrDefault(Settings.REVIEW_SLA, ""),
                plain.getOrDefault(Settings.PROOF_KINDS, ""), plain.getOrDefault(Settings.DEFAULT_GRADE, ""),
